class Solution:
    def resultingString(self, s: str) -> str:
        st = []
        for c in s:
            if st:
                d = abs(ord(st[-1]) - ord(c))
                if d == 1 or d == 25:
                    st.pop()
                    continue
            st.append(c)
        return ''.join(st)

