class Solution {
    public String resultingString(String s) {
        StringBuilder st = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (st.length() > 0) {
                int d = Math.abs(st.charAt(st.length() - 1) - c);
                if (d == 1 || d == 25) { st.deleteCharAt(st.length() - 1); continue; }
            }
            st.append(c);
        }
        return st.toString();
    }
}

