class Solution:
    def resultingString(self, s: str) -> str:
        t = list(s)
        changed = True
        while changed:
            changed = False
            for i in range(len(t) - 1):
                d = abs(ord(t[i]) - ord(t[i+1]))
                if d == 1 or d == 25:
                    del t[i:i+2]
                    changed = True
                    break
        return ''.join(t)

