    string resultingString(string s) {
        bool changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i + 1 < (int)s.size(); i++) {
                int d = abs(s[i] - s[i+1]);
                if (d == 1 || d == 25) { s.erase(i, 2); changed = true; break; }
            }
        }
        return s;
    }
};

