        boolean changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i + 1 < t.length(); i++) {
                int d = Math.abs(t.charAt(i) - t.charAt(i + 1));
                if (d == 1 || d == 25) { t.delete(i, i + 2); changed = true; break; }
            }
        }
        return t.toString();
    }
}

